const B=(symbol,type)=>({symbol,type});
const def=(id,symbol,type,definition,depends_on=[],objects=[],binders=[],requires=[])=>({id,symbol,type,definition,depends_on,requires,binders,objects});
const Ds=[
def("D001","Eucl","nonnegative integer → Euclidean metric space","For each nonnegative integer k, Eucl(k)=R^k is the space of real k-tuples, with distance (sum_{j=1}^k |x_j-y_j|^2)^(1/2) and its Borel sigma algebra. The empty tuple is the sole point of Eucl(0). Eucl(k)×R is identified with Eucl(k+1) by adjoining the last coordinate; this identification uses the Euclidean distance sqrt(||x-y||_2^2+|t-u|^2).",[],[],[B("k","nonnegative integer"),B("x","point of Eucl(k)"),B("y","point of Eucl(k)"),B("t","real"),B("u","real")]),
def("D002","diam","diameter function on subsets of metric or extended metric spaces","diam(A)=sup{dist(x,y): x,y in A}, as an extended nonnegative number, with supremum of the empty set zero. Thus diam(empty)=0. In ordinary Euclidean spaces a nonempty set of diameter zero is a singleton. Native ediam is this extended-valued diameter. Euclidean finite diameters are identified with their nonnegative real values.",[],[],[B("A","subset of a metric or extended metric space")]),
def("D003","H","positive exponent and scale Hausdorff contents and limiting Hausdorff measure on Euclidean sets",{from_task:"problem.md",start_line:34,end_line:42},["D001","D002"],["Eucl","diam"],[B("A","subset of a Euclidean space"),B("s","positive real"),B("delta","positive real"),B("U_i","countable family of subsets of the same Euclidean space")]),
def("D004","muH","real exponent → Borel Hausdorff measure on any extended metric space","muH(a) denotes the native unnormalized Borel Hausdorff measure MeasureTheory.Measure.hausdorffMeasure a: the metric outer-measure construction mkMetric with gauge r↦r^a on extended nonnegative diameters. Its value on an arbitrary set is its outer-measure value, without a measurability requirement on that set. Empty covering members have cost zero; nonempty members have cost diam^a, using extended nonnegative real powers. At a=0 the nonempty-member cost, including singletons, is 1. The complete countable-cover evaluation formula is supplied by M002.",["D002"],["diam"],[B("a","real")]),
def("D005","dimH","Hausdorff dimension of subsets of metric spaces, valued in [0,infinity]","dimH(A), also written dim_H A, is the standard Hausdorff dimension: sup({a≥0 : muH(a)(A)=infinity}) in [0,infinity], where the supremum of an empty set is 0. This is precisely the native dimH definition. In particular dimH(empty)=0. Positive-exponent normalization to the supplied H is proved in N001; no critical-exponent property is assumed by this definition.",["D004"],["muH"],[B("A","subset of an extended metric space")]),
def("D006","I","subset of R","I=[0,1]={t in R:0≤t≤1}.",[],[]),
def("D007","F","subset of Eucl(n+1)","F=E×I under the Euclidean identification in D001.",["D001","D006"],["E","n","Eucl","I"]),
def("D008","D","extended nonnegative real","D=dimH(E). Real arithmetic involving D is used only after N002 proves D finite.",["D005"],["dimH","E"]),
def("D009","lambda","Lebesgue measure on R and associated integral notation","lambda is Lebesgue measure on R with its Borel measurable structure, completed when needed. For a Borel set J, |J| denotes lambda(J). The symbol 1_J denotes its indicator, equal to 1 on J and 0 elsewhere. Integrals of nonnegative functions are extended Lebesgue integrals (native lintegral). Restriction to I is the measure lambda restricted to [0,1]. Thus lambda(I)=1 and an open bounded interval (a,b) has measure b-a.",["D006"],["I"],[B("J","Borel subset of R"),B("a","real"),B("b","real")])
];
