text({definitions:r.definitions.filter(d=>JSON.stringify(d)!==JSON.stringify(seen[d.id])),definitions_identical_to_already_read:r.definitions.filter(d=>JSON.stringify(d)===JSON.stringify(seen[d.id])).map(d=>d.id),inputs:r.inputs,output:r.output,inference:r.inference});
