const obj=r=>typeof r==="string"?JSON.parse(r):r;
const diff=(a,b,path="")=>{
 if(JSON.stringify(a)===JSON.stringify(b))return [];
 if(a===null||b===null||typeof a!=="object"||typeof b!=="object"||Array.isArray(a)!==Array.isArray(b))return [{path,value:b}];
 const out=[];for(const key of new Set([...Object.keys(a),...Object.keys(b)]))out.push(...diff(a[key],b[key],path+"/"+key));return out;
};
for(const id of ["R002","R003","R004","R006"]){
 const r=obj(await tools.read_author_packet({candidate:7,inference:id}));
 const old=load("packet"+id);
 text({inference:id,candidate:r.candidate,compared_to_actual_packet_candidate:old.candidate,mathematical_changes:diff({parameters:old.parameters,logic:old.logic,definitions:old.definitions,inputs:old.inputs,output:old.output,inference:old.inference},{parameters:r.parameters,logic:r.logic,definitions:r.definitions,inputs:r.inputs,output:r.output,inference:r.inference})});
 store("packet"+id,r);
}
